#include <windows.h>
#include "GameClient/KeyDefs.h"
#include "GameClient/Win32DIKeyboard.h"

extern void *ApplicationHInstance;
extern void *ApplicationHWnd;

enum { KEYBOARD_BUFFER_SIZE = 256 };

// FUNCTION: BFME2 0x00098A6F size=61 name=?closeKeyboard@DirectInputKeyboard@@IAEXXZ evidence=N:ledger tier=B hypothesis:name:Z
void DirectInputKeyboard::closeKeyboard()
{
	if (m_pKeyboardDevice)
	{
		m_pKeyboardDevice->Unacquire();
		m_pKeyboardDevice->Release();
		m_pKeyboardDevice = NULL;
	}
	if (m_pDirectInput)
	{
		m_pDirectInput->Release();
		m_pDirectInput = NULL;
	}
}

// FUNCTION: BFME2 0x00098AAC size=169 name=?getKey@DirectInputKeyboard@@MAEXPAUKeyboardIO@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void DirectInputKeyboard::getKey(KeyboardIO *key)
{
	DIDEVICEOBJECTDATA kbdat;
	DWORD num = 0;
	HRESULT hr;

	key->sequence = 0;
	key->key = KEY_NONE;

	if (m_pKeyboardDevice)
	{
		num = 1;
		hr = m_pKeyboardDevice->Acquire();
		if (hr == DI_OK || hr == S_FALSE)
			hr = m_pKeyboardDevice->GetDeviceData(sizeof(DIDEVICEOBJECTDATA), &kbdat, &num, 0);

		switch (hr)
		{
			case DI_OK:
				break;

			case DIERR_INPUTLOST:
			case DIERR_NOTACQUIRED:
				hr = m_pKeyboardDevice->Acquire();
				switch (hr)
				{
					case DIERR_INVALIDPARAM:
					case DIERR_NOTINITIALIZED:
					case DIERR_OTHERAPPHASPRIO:
						break;

					case DI_OK:
					case S_FALSE:
						key->key = KEY_LOST;
						break;
				}
				return;

			default:
				return;
		}

		if (num == 0)
			return;

		key->key = (UnsignedByte)(kbdat.dwOfs & 0xFF);
		key->sequence = kbdat.dwSequence;
		key->state = ((kbdat.dwData & 0x0080) ? KEY_STATE_DOWN : KEY_STATE_UP);
		key->status = KeyboardIO::STATUS_UNUSED;
	}
}

// FUNCTION: BFME2 0x00098B55 size=54 name=??0DirectInputKeyboard@@QAE@XZ evidence=N:ledger tier=B hypothesis:cohesion
DirectInputKeyboard::DirectInputKeyboard()
{
	m_pDirectInput = NULL;
	m_pKeyboardDevice = NULL;

	// the caps-lock bit the retail constructor sets when the key is toggled on (0x0200 of the modifier word at +0x0C)
	if (GetKeyState(VK_CAPITAL) & 0x01)
		m_modifiers |= 0x0200;
	else
		m_modifiers &= ~0x0200;
}

// FUNCTION: BFME2 0x00098B8B size=56 name=??1DirectInputKeyboard@@UAE@XZ evidence=N:ledger tier=B hypothesis:cohesion
DirectInputKeyboard::~DirectInputKeyboard()
{
	closeKeyboard();
}

// FUNCTION: BFME2 0x00098BC8 size=12 name=?getCapsState@DirectInputKeyboard@@UAE_NXZ evidence=N:ledger tier=B hypothesis:cohesion
bool DirectInputKeyboard::getCapsState()
{
	return (GetKeyState(VK_CAPITAL) & 0x01) != 0;
}

// FUNCTION: BFME2 0x00098BD4 size=188 name=?openKeyboard@DirectInputKeyboard@@IAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void DirectInputKeyboard::openKeyboard()
{
	HRESULT hr;

	hr = DirectInput8Create((HINSTANCE)ApplicationHInstance, DIRECTINPUT_VERSION, IID_IDirectInput8, (void **)&m_pDirectInput, NULL);
	if (FAILED(hr))
	{
		closeKeyboard();
		return;
	}

	hr = m_pDirectInput->CreateDevice(GUID_SysKeyboard, &m_pKeyboardDevice, NULL);
	if (FAILED(hr))
	{
		closeKeyboard();
		return;
	}

	hr = m_pKeyboardDevice->SetDataFormat(&c_dfDIKeyboard);
	if (FAILED(hr))
	{
		closeKeyboard();
		return;
	}

	hr = m_pKeyboardDevice->SetCooperativeLevel((HWND)ApplicationHWnd, DISCL_FOREGROUND | DISCL_NONEXCLUSIVE);
	if (FAILED(hr))
	{
		closeKeyboard();
		return;
	}

	DIPROPDWORD prop;
	prop.diph.dwSize = sizeof(DIPROPDWORD);
	prop.diph.dwHeaderSize = sizeof(DIPROPHEADER);
	prop.diph.dwObj = 0;
	prop.diph.dwHow = DIPH_DEVICE;
	prop.dwData = KEYBOARD_BUFFER_SIZE;
	hr = m_pKeyboardDevice->SetProperty(DIPROP_BUFFERSIZE, &prop.diph);
	if (FAILED(hr))
	{
		closeKeyboard();
		return;
	}

	hr = m_pKeyboardDevice->Acquire();
	if (FAILED(hr))
		return;
}

// FUNCTION: BFME2 0x00098CAC size=16 name=?init@DirectInputKeyboard@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void DirectInputKeyboard::init()
{
	Keyboard::init();
	openKeyboard();
}

